mapper.insert:
	/* Baim02Mapper.mergeCmmCodeDetailInfo */	
    INSERT INTO TB_BAIM_VAL_D (
    	CMPNY_CD
    	, BAIM_VAL_CD
    	, BAIM_VAL_D_CD
    	, BAIM_VAL_D_NM
    	, SORT_IDX
    	, USE_YN
    	, VAL_D_INFO_1
    	, VAL_D_INFO_2
    	, VAL_D_DESC
    	, INSERT_NO
    	, INSERT_DATE
    	, UPDATE_NO
    	, UPDATE_DATE
   	)
   	VALUES(
   		#{gvCmpnyCd}
   		, #{baimValCd}
   		, IFNULL(#{baimValDCd}, FNC_CMM_SEQ_NEXTVAL(#{gvCmpnyCd}, #{baimValCd}))
   		, #{baimValDNm}
   		, #{sortIdx}
		, #{useYn}
		, #{valDInfo1}
		, #{valDInfo2}
		, #{valDDesc}
		, #{gvUserCd}
		, now()
		, #{gvUserCd}
		, now() 
   	) AS NEW
   	ON DUPLICATE KEY UPDATE
	    USE_YN     		= NEW.USE_YN
	    , BAIM_VAL_D_NM = NEW.BAIM_VAL_D_NM
	    , SORT_IDX		= NEW.SORT_IDX
	    , USE_YN		= IFNULL(NEW.USE_YN, 'Y')
	    , VAL_D_INFO_1	= NEW.VAL_D_INFO_1
    	, VAL_D_INFO_2	= NEW.VAL_D_INFO_2
    	, VAL_D_DESC	= NEW.VAL_D_DESC
	    , UPDATE_NO   	= NEW.UPDATE_NO
	    , UPDATE_DATE 	= NOW()

mapper.update:
/* Baim02Mapper.mergeCmmCodeDetailInfo */
UPDATE TB_BAIM_VAL_D 
SET USE_YN = 'N'
	, UPDATE_NO = #{gvUserCd}
	, UPDATE_DATE = now()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND BAIM_VAL_CD = #{baimValCd}
  AND BAIM_VAL_D_CD = #{baimValDCd}
